import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// Auth middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token validation happens upstream via API gateway
  req.userId = Buffer.from(token, 'base64').toString().split(':')[0];
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/products/search', authenticate, async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order, fields } = req.query;

    // Build base query
    let query = 'SELECT ';

    // Field selection - allows caller to specify returned columns
    if (fields) {
      const allowedFields = ['id', 'name', 'price', 'category', 'description', 'sku'];
      const requestedFields = fields.split(',').map(f => f.trim());
      const validFields = requestedFields.filter(f => allowedFields.includes(f));
      query += validFields.length > 0 ? validFields.join(', ') : '*';
    } else {
      query += '*';
    }

    query += ' FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      params.push(category);
      query += ` AND category = $${paramIdx++}`;
    }

    if (minPrice) {
      params.push(parseFloat(minPrice));
      query += ` AND price >= $${paramIdx++}`;
    }

    if (maxPrice) {
      params.push(parseFloat(maxPrice));
      query += ` AND price <= $${paramIdx++}`;
    }

    // Sort - vulnerability: sortBy and order are interpolated directly
    if (sortBy) {
      query += ` ORDER BY ${sortBy}`;
      if (order) {
        query += ` ${order}`;
      }
    }

    query += ' LIMIT 100';

    const result = await pool.query(query, params);

    // Audit log
    const logId = crypto.randomUUID();
    await pool.query(
      'INSERT INTO audit_log (id, user_id, action, query_text, ts) VALUES ($1, $2, $3, $4, NOW())',
      [logId, req.userId, 'product_search', query]
    );

    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin endpoint for bulk operations
app.post('/api/v2/products/bulk-update', authenticate, async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'invalid payload' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      await client.query(
        'UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2 AND tenant_id = $3',
        [u.price, u.id, req.userId]
      );
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'bulk update failed' });
  } finally {
    client.release();
  }
});

app.listen(8080, () => console.log('Product service listening on 8080'));
